from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from typing import Any


_CENT = Decimal("0.01")


def _number(value: Any) -> Decimal:
    """Apply the legacy NVL/numeric coercion rules."""
    if value is None:
        return Decimal(0)
    if isinstance(value, str):
        value = value.strip()
        if not value:
            return Decimal(0)
    if isinstance(value, Decimal):
        return value
    if isinstance(value, bool):
        return Decimal(int(value))
    try:
        # Converting through str avoids importing binary-float artifacts.
        return Decimal(str(value))
    except (InvalidOperation, ValueError, TypeError):
        return Decimal(0)


def _rounded_cents(value: Decimal) -> Decimal:
    return value.quantize(_CENT, rounding=ROUND_HALF_UP)


def recompute(order: dict, lines: list[dict]) -> tuple[dict, list[dict], list]:
    new_order = dict(order)
    new_lines = [dict(line) for line in lines]

    if order.get("DEL_FLG") == "Y" or order.get("STAT_CD") == "X":
        return new_order, new_lines, []

    total = Decimal(0)

    for line in new_lines:
        if line.get("DEL_FLG") == "Y":
            continue

        quantity = _number(line.get("QTY"))
        unit_price = _number(line.get("UNIT_PRC"))
        extension = _rounded_cents(quantity * unit_price)
        line["EXT_AMT"] = float(extension)
        total += extension

    discount = _number(order.get("DISC_PCT"))
    discounted = _rounded_cents(total * (Decimal(100) - discount) / Decimal(100))

    incoming_total = _number(order.get("TOT_AMT"))
    audits = []

    new_order["TOT_AMT"] = float(discounted)
    if incoming_total != discounted:
        audits.append(("ORD_RETOTAL", order.get("ORD_ID")))

    return new_order, new_lines, audits
